import{_ as a,o as t,c as s,ag as o}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"nay-lib/permissions.md","filePath":"nay-lib/permissions.md"}'),n={name:"nay-lib/permissions.md"};function i(d,e,r,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>Every Nayretis action that needs rights checks a <strong>scope</strong>. You grant scopes with ACE, with rules stored in the database, or from the Permissions tab of <code>/nay</code>.</p><h2 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Grants</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Everything: every script, the Nayretis settings, permissions, API tokens, webhooks and the audit log.</td></tr><tr><td><code>nay.config</code></td><td>The settings of every script.</td></tr><tr><td><code>nay.audit</code></td><td>The audit log.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>The settings of one script, for example <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>A permission declared by a script, listed on its page.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Every scope of one script.</td></tr></tbody></table><h2 id="with-ace" tabindex="-1">With ACE <a class="header-anchor" href="#with-ace" aria-label="Permalink to &quot;With ACE&quot;">​</a></h2><p>An ACE on a scope grants it. In <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="with-rules" tabindex="-1">With rules <a class="header-anchor" href="#with-rules" aria-label="Permalink to &quot;With rules&quot;">​</a></h2><p>Rules are stored in the database and can target a player directly. A rule has a type, an identifier and a scope. The types are:</p><ul><li><code>ace</code>: every player allowed on that ACE object;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code>: one player, by identifier.</li></ul><p>From the server console:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> and <code>nay_revoke</code> take <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> lists every rule with its number.</p><p>In game, the <strong>Permissions</strong> tab of <code>/nay</code> (scope <code>nay.admin</code>) lists, adds and removes the same rules. Every change is written to the <a href="/nay-lib/audit">audit log</a>.</p>`,14)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
